/**
 * TASK: Measure how long a key is held down.
 *
 * While a key is held, the system repeats it: keyPressed fires again and
 * again for the SAME key code before any other key arrives. Register a
 * KeyListener whose keyPressed turns that into a streak:
 *
 *   - pressing the same key code as last time makes the streak one longer
 *   - pressing a different key code starts a new streak of 1
 *   - the longest streak seen so far is remembered separately
 *
 * streak() is 0 before any key arrives, longestStreak() is 0 too, and
 * currentKeyText() is "none" until the first press -- afterwards it is
 * KeyEvent.getKeyText(code) for the key being repeated, for example "A".
 *
 * Example: A, A, A, B -> streak() is 1 (B has only just started),
 * longestStreak() is 3 and currentKeyText() is "B".
 *
 * KeyListener has three methods; extending java.awt.event.KeyAdapter and
 * overriding only keyPressed keeps the code short.
 *
 * No window is ever opened -- the tests build KeyEvents by hand and hand
 * them straight to the registered listener.
 */
import javax.swing.JPanel;

public class KeyStreakTracker extends JPanel {

    private int lastCode = -1;
    private int streak = 0;
    private int longest = 0;

    public KeyStreakTracker() {
        // TODO: addKeyListener(...) so keyPressed grows or restarts the streak
        // TODO: and keeps the longest streak up to date
    }

    public int streak() {
        // TODO: length of the run of presses of the current key
        return 0;
    }

    public int longestStreak() {
        // TODO: the longest run seen so far
        return 0;
    }

    public String currentKeyText() {
        // TODO: KeyEvent.getKeyText of the current key, or "none"
        return "";
    }
}

