import java.awt.event.KeyEvent;
import java.awt.event.KeyListener;

public class KeyStreakTrackerTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    static java.awt.Component find(java.awt.Container root, String name) {
        if (name.equals(root.getName())) {
            return root;
        }
        for (java.awt.Component child : root.getComponents()) {
            if (name.equals(child.getName())) {
                return child;
            }
            if (child instanceof java.awt.Container) {
                java.awt.Component result = find((java.awt.Container) child, name);
                if (result != null) {
                    return result;
                }
            }
        }
        return null;
    }

    static String textOf(java.awt.Component c) {
        if (c instanceof javax.swing.JLabel) {
            return ((javax.swing.JLabel) c).getText();
        }
        if (c instanceof javax.swing.text.JTextComponent) {
            return ((javax.swing.text.JTextComponent) c).getText();
        }
        return "(missing)";
    }

    static void press(KeyStreakTracker panel, int keyCode) {
        KeyEvent event = new KeyEvent(panel, KeyEvent.KEY_PRESSED,
                System.currentTimeMillis(), 0, keyCode, KeyEvent.CHAR_UNDEFINED);
        for (KeyListener listener : panel.getKeyListeners()) {
            listener.keyPressed(event);
        }
    }

    static void press(KeyStreakTracker panel, int keyCode, int times) {
        for (int i = 0; i < times; i++) {
            press(panel, keyCode);
        }
    }

    public static void main(String[] args) {
        try {
            KeyStreakTracker panel = new KeyStreakTracker();
            check("a KeyListener is registered", true, panel.getKeyListeners().length >= 1);
            check("streak starts at 0", 0, panel.streak());
            check("longest starts at 0", 0, panel.longestStreak());
            check("no current key yet", "none", panel.currentKeyText());

            press(panel, KeyEvent.VK_A);
            check("first press starts a streak of one", 1, panel.streak());
            check("current key after one press", "A", panel.currentKeyText());

            press(panel, KeyEvent.VK_A, 2);
            check("repeats grow the streak", 3, panel.streak());
            check("longest keeps up", 3, panel.longestStreak());

            press(panel, KeyEvent.VK_B);
            check("a different key restarts the streak", 1, panel.streak());
            check("the record is kept", 3, panel.longestStreak());
            check("current key after switching", "B", panel.currentKeyText());

            press(panel, KeyEvent.VK_B, 4);
            check("a longer run beats the record", 5, panel.longestStreak());
        } catch (Throwable t) {
            System.out.println("FAIL  unexpected problem -- " + t);
            failures++;
        }
        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

